# ---------------- CONECTIVOS ----------------
CO='Valores: CONCESSÃO embora, ainda que, apesar de; OPOSIÇÃO/ADVERSIDADE mas, porém, contudo, todavia; CAUSA/EXPLICAÇÃO porque, pois (antes do verbo), já que, visto que; CONCLUSÃO portanto, logo, por isso, pois (depois do verbo); CONDIÇÃO se, caso, desde que; FINALIDADE para, a fim de; CONFORMIDADE conforme, segundo, consoante; PROPORÇÃO à medida que, à proporção que; ADIÇÃO e, além disso, ademais; preposição COM pode indicar causa ("com o fundo de madeira, ficou mais pesada").'
def c(id,top,enun,gab,alt=None,orig=None,tags=None,origem=None): q(id,P6,GR,top,enun,gab,CO,alt=alt,orig=orig,tags=tags or R,origem=origem)
