v('POR-VO-05','prescindível','"Prescindível" significa indispensável.','E','Prescindir = dispensar. Prescindível = dispensável. Imprescindível = indispensável.',alt='indispensável',orig='dispensável')
v('POR-VO-06','ratificar','"Ratificar" significa corrigir, emendar.','E','Ratificar = confirmar, validar. Retificar = corrigir.',alt='corrigir, emendar',orig='confirmar, validar',tags=J,origem=VU(2024,'Escrevente Técnico Judiciário — TJ-SP (reaplicação)'))
v('POR-VO-07','recrudescimento','"O recrudescimento do desemprego" indica que o desemprego se intensificou.','C','Recrudescer = intensificar-se, agravar-se, aumentar.',tags=J,origem=VU(2023))
v('POR-VO-08','conciso','O antônimo de "conciso" é "lacônico".','E','Conciso, lacônico e sucinto são sinônimos (breve, resumido). Antônimo: prolixo (que se alonga demais).',alt='é "lacônico"',orig='Antônimo: prolixo',tags=J,origem=VU(2024))
v('POR-VO-09','impassível','Uma pessoa "impassível" diante da tragédia mostra-se imperturbável, sem demonstrar emoção.','C','Impassível/impassiva = imperturbável, indiferente, que não demonstra emoção.',tags=J,origem=VU(2025))
v('POR-VO-10','profícuo','"Contribuições profícuas" são contribuições proveitosas, úteis.','C','Profícuo = proveitoso, útil, vantajoso.',tags=J,origem=VU(2025))
v('POR-VO-11','burburinho','"Burburinho da cidade" significa silêncio da cidade.','E','Burburinho = ruído confuso de vozes, agitação, tumulto.',alt='silêncio da cidade',orig='ruído confuso de vozes, agitação, tumulto',tags=J,origem=VU(2024,'Escrevente Técnico Judiciário — TJ-SP (reaplicação)'))
v('POR-VO-12','estrebuchar','"As metrópoles estrebucham entre dois extremos" significa que elas se debatem, se agitam, entre os extremos.','C','Estrebuchar = debater-se, agitar-se convulsivamente.',tags=J,origem=VU(2024,'Escrevente Técnico Judiciário — TJ-SP (reaplicação)'))
v('POR-VO-13','implicar','Em "a nacionalidade implica submissão à autoridade", "implica" equivale a "pressupõe".','C','Implicar (transitivo direto) = acarretar, pressupor, envolver.',tags=J,origem=VU(2023))
v('POR-VO-14','vultoso','"Valor vultoso" é valor de grande monta.','C','Vultoso = volumoso, de grande valor. Vultuoso = inchado (face vultuosa).')
v('POR-VO-15','arremedo','"Um arremedo de legitimidade" é uma legitimidade plena e reconhecida.','E','Arremedo = imitação malfeita, simulacro.',alt='uma legitimidade plena e reconhecida',orig='imitação malfeita',tags=J,origem=VU(2024))
v('POR-VO-16','sufragista','Dizer que alguém foi uma das "primeiras sufragistas" significa que defendia o direito de voto das mulheres.','C','Sufrágio = voto. Sufragista = quem lutou pelo direito de voto feminino.',tags=J,origem=VU(2023))
